def drive(me, enemy, arena):
    if not me.can_drive:
        return (0, 0)
    h = radians(enemy.heading)
    lx = -sin(h)
    ly = cos(h)
    rx = sin(h)
    ry = -cos(h)
    dist = distance_to(enemy.x, enemy.y)
    a = atan2(me.y - enemy.y, me.x - enemy.x)
    rel = degrees(a) - enemy.heading
    rel = (rel + 180) % 360 - 180
    wfront = enemy.wedges.get("front")
    wedge = wfront is not None and wfront["life"] > 0
    front = wedge and abs(rel) < 45 and dist < 2.8
    side = me.memory.get("side", 0)
    if front:
        off = 0.55 if dist > 1.2 else 0.35
        tx1 = enemy.x + lx * off
        ty1 = enemy.y + ly * off
        tx2 = enemy.x + rx * off
        ty2 = enemy.y + ry * off
        d1 = hypot(tx1 - me.x, ty1 - me.y)
        d2 = hypot(tx2 - me.x, ty2 - me.y)
        lw = enemy.wedges.get("left")
        rw = enemy.wedges.get("right")
        if lw is not None and lw["life"] > 0:
            d1 = d1 + 1.0
        if rw is not None and rw["life"] > 0:
            d2 = d2 + 1.0
        if side == 0:
            side = 1 if d1 <= d2 else -1
        elif side == 1 and d2 + 0.5 < d1:
            side = -1
        elif side == -1 and d1 + 0.5 < d2:
            side = 1
        me.memory["side"] = side
        if side == 1:
            tx = tx1
            ty = ty1
        else:
            tx = tx2
            ty = ty2
    else:
        tx = enemy.x
        ty = enemy.y
    td = hypot(tx, ty)
    if td > 6.2:
        tx = tx * 6.2 / td
        ty = ty * 6.2 / td
    ang = bearing_to(tx, ty)
    d = distance_to(tx, ty)
    if d < 0.25:
        speed = 0.5
    elif d < 0.7:
        speed = 0.6
    elif d < 1.8:
        speed = 0.8
    else:
        speed = 1.0
    if abs(ang) > 60:
        speed = 0.6
    elif abs(ang) > 30:
        if speed > 0.8:
            speed = 0.8
    steer = ang * 0.03
    if steer > 0.9:
        steer = 0.9
    elif steer < -0.9:
        steer = -0.9
    left = speed - steer
    right = speed + steer
    if left < -1:
        left = -1
    elif left > 1:
        left = 1
    if right < -1:
        right = -1
    elif right > 1:
        right = 1
    return (left, right)

def weapons(me, enemy, arena):
    if "front" not in me.weapons:
        return None
    if not me.can_drive:
        return None
    w = me.weapons["front"]
    rpm = w["rpm"]
    temp = w["temperature"]
    health = w["health"]
    base = 2800
    if temp > 130:
        base = 1500
    elif temp > 110:
        base = 2000
    elif temp > 95:
        base = 2400
    if health < 0.5:
        base = 2000
    if health < 0.3:
        base = 1500
    if rpm > base:
        target = rpm
    elif rpm < base:
        if temp > 120:
            target = rpm
        else:
            gap = base - rpm
            if gap > 500:
                inc = 80
            elif gap > 200:
                inc = 40
            else:
                inc = 20
            target = rpm + inc
            if target > base:
                target = base
    else:
        target = base
    if target < 0:
        target = 0
    if target > w["max_rpm"]:
        target = w["max_rpm"]
    return spin("front", target)

